CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS food_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, description VARCHAR(500) NOT NULL, category VARCHAR(40) NOT NULL, price DECIMAL(10,2) NOT NULL, image_url VARCHAR(600) NOT NULL, is_vegetarian BOOLEAN NOT NULL DEFAULT TRUE, rating DECIMAL(2,1) NOT NULL DEFAULT 4.5, available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS cart (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, food_item_id BIGINT NOT NULL, quantity INT NOT NULL DEFAULT 1, UNIQUE(user_id, food_item_id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (food_item_id) REFERENCES food_items(id));
CREATE TABLE IF NOT EXISTS orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, delivery_address VARCHAR(500) NOT NULL, payment_mode VARCHAR(20) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, tax DECIMAL(10,2) NOT NULL, delivery_fee DECIMAL(10,2) NOT NULL, discount DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'Placed', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, food_item_id BIGINT NOT NULL, item_name VARCHAR(160) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (food_item_id) REFERENCES food_items(id));
CREATE TABLE IF NOT EXISTS reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, food_item_id BIGINT NOT NULL, rating INT NOT NULL, comment VARCHAR(600) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (food_item_id) REFERENCES food_items(id));
CREATE TABLE IF NOT EXISTS contacts (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, message VARCHAR(1200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons (code VARCHAR(40) PRIMARY KEY, discount_percent INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
